SELECT DISTINCTROW qryElektrolyseureInTeilanlage.Teilanlagenbezeichnung, [Gesamt Normierung Zeitraum].Datum, Avg([Gesamt Normierung Zeitraum].[I Gesamt]) AS [Mittelwert von I Gesamt], Avg([Gesamt Normierung Zeitraum].i) AS [Mittelwert von i], Avg([Gesamt Normierung Zeitraum].Cc) AS [Mittelwert von Cc], Avg([Gesamt Normierung Zeitraum].[t An]) AS [Mittelwert von t An], Avg([Gesamt Normierung Zeitraum].[t Ka]) AS [Mittelwert von t Ka], Avg([Gesamt Normierung Zeitraum].tm) AS [Mittelwert von tm], [Gesamt Normierung Zeitraum].Uo, Avg([Gesamt Normierung Zeitraum].Ui) AS [Mittelwert von Ui], Avg([Gesamt Normierung Zeitraum].Uk) AS [Mittelwert von Uk], [Gesamt Normierung Zeitraum].iRef, [Gesamt Normierung Zeitraum].tKorr, [Gesamt Normierung Zeitraum].cKorr, Avg([Gesamt Normierung Zeitraum].Un) AS [Mittelwert von Un], Count([Gesamt Normierung Zeitraum].Position) AS [Anzahl von Position]
FROM tblGewDaten, [Gesamt Normierung Zeitraum] INNER JOIN qryElektrolyseureInTeilanlage ON [Gesamt Normierung Zeitraum].Elektrolyseur = qryElektrolyseureInTeilanlage.Elektrolyseurbezeichnung
GROUP BY qryElektrolyseureInTeilanlage.Teilanlagenbezeichnung, [Gesamt Normierung Zeitraum].Datum, [Gesamt Normierung Zeitraum].Uo, [Gesamt Normierung Zeitraum].iRef, [Gesamt Normierung Zeitraum].tKorr, [Gesamt Normierung Zeitraum].cKorr;
